arguments.old:
    // detent plate on the gear, underside flush with the gear top,
    // with a 45 deg conical lead-in from the gear OD
    translate([0, 0, gear_h]) cylinder(r = 12, h = 2.5, $fn = 72);
    translate([0, 0, gear_h - 1]) cylinder(r1 = 13.5, r2 = 12, h = 1, $fn = 72);
    // crank peg, standing up at radius 7.5 (clear of the notches)
    translate([0, 7.5, gear_h]) cylinder(r = 2.6, h = 11.5, $fn = 36);
}
translate([0, 0, -1]) cylinder(r = bore_r, h = 20, $fn = 48);
// four deep V notches (blind: 1.5 mm of roof above the cavity):
// the base bump clicks in every quarter turn
for (a = [0, 90, 180, 270])
    rotate([0, 0, a]) translate([0, -10.6, gear_h - 2])
        cylinder(r1 = 2.6, r2 = 1.2, h = 3, $fn = 32);

arguments.new:
    // detent flange (r 11, clear of gear 2) on the gear top,
    // with a 45 deg conical lead-in from the gear OD
    translate([0, 0, gear_h]) cylinder(r = 11, h = 2.5, $fn = 72);
    translate([0, 0, gear_h - 1]) cylinder(r1 = 12, r2 = 11, h = 1, $fn = 72);
    // crank peg at radius 7.5, at 45 deg between detent slots
    translate([5.3, 5.3, gear_h]) cylinder(r = 2.6, h = 11.5, $fn = 36);
}
translate([0, 0, -1]) cylinder(r = bore_r, h = 20, $fn = 48);
// four radial detent slots through the full flange height:
// the base bump clicks in every quarter turn
for (a = [0, 90, 180, 270])
    rotate([0, 0, a]) translate([-1.3, -11.8, gear_h - 0.1])
        cube([2.6, 4, 2.7]);
